import apiClient from './client'

export type HealActionType = 'builtin' | 'custom_script'
export type HealRiskLevel = 'low' | 'medium' | 'high'

export interface HealActionRead {
  id: number
  action_id: string
  name: string
  description?: string | null
  action_type: HealActionType
  script_content?: string | null
  script_hash?: string | null
  parameter_schema: Record<string, unknown>
  risk_level: HealRiskLevel
  is_approved: boolean
  is_builtin: boolean
  created_at: string
  updated_at: string
}

export interface HealActionCreate {
  action_id: string
  name: string
  description?: string
  action_type?: HealActionType
  script_content?: string
  parameter_schema?: Record<string, unknown>
  risk_level?: HealRiskLevel
}

export interface HealActionUpdate {
  name?: string
  description?: string
  script_content?: string
  parameter_schema?: Record<string, unknown>
  risk_level?: HealRiskLevel
}

export interface ApproveResponse {
  id: number
  action_id: string
  is_approved: boolean
}

export async function getHealActions(riskLevel?: HealRiskLevel): Promise<HealActionRead[]> {
  const response = await apiClient.get<HealActionRead[]>('/v1/heal-actions', {
    params: riskLevel ? { risk_level: riskLevel } : {},
  })
  return response.data
}

export async function createHealAction(data: HealActionCreate): Promise<HealActionRead> {
  const response = await apiClient.post<HealActionRead>('/v1/heal-actions', data)
  return response.data
}

export async function getHealAction(actionId: number): Promise<HealActionRead> {
  const response = await apiClient.get<HealActionRead>(`/v1/heal-actions/${actionId}`)
  return response.data
}

export async function updateHealAction(
  actionId: number,
  data: HealActionUpdate
): Promise<HealActionRead> {
  const response = await apiClient.put<HealActionRead>(`/v1/heal-actions/${actionId}`, data)
  return response.data
}

export async function deleteHealAction(actionId: number): Promise<void> {
  await apiClient.delete(`/v1/heal-actions/${actionId}`)
}

export async function approveHealAction(actionId: number): Promise<ApproveResponse> {
  const response = await apiClient.post<ApproveResponse>(`/v1/heal-actions/${actionId}/approve`)
  return response.data
}
